def localized_plan(plan, language: str | None = None):
    from types import SimpleNamespace

    language = clean_language(language)
    text = PLAN_TEXT.get(plan.code, {})
    plan_features = PLAN_FEATURES_BY_PLAN.get(plan.code, {})
    return SimpleNamespace(
        code=plan.code,
        name=plan.name,
        badge=text.get("badge", {}).get(language, text.get("badge", {}).get(DEFAULT_LANGUAGE, plan.badge)),
        price_cents=plan.price_cents,
        currency=plan.currency,
        period_days=plan.period_days,
        price_display=plan.price_display,
        price_label=f"{plan.price_display} / {plan.period_days} " + translate("days", language),
        storage_bytes=plan.storage_bytes,
        storage_text=_human_storage(plan.storage_bytes),
        headline=text.get("headline", {}).get(language, text.get("headline", {}).get(DEFAULT_LANGUAGE, plan.headline)),
        description=text.get("description", {}).get(language, text.get("description", {}).get(DEFAULT_LANGUAGE, plan.description)),
        features=plan_features.get(language, plan_features.get(DEFAULT_LANGUAGE, PLAN_FEATURES.get(language, PLAN_FEATURES[DEFAULT_LANGUAGE]))),
    )


def _human_storage(size: int) -> str:
    amount = float(size)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if amount < 1024 or unit == "TB":
            return f"{amount:.1f} {unit}" if unit != "B" else f"{int(amount)} B"
        amount /= 1024


